// План specs/admin-coupons.md 2.1–2.3 (кейсы CP-05…CP-07). Admin, десктоп, EN, компания test (возврат в finally).
// @prod-safe: только просмотр списка, поиск и фильтр; купоны не создаются и не меняются (страховка blockCouponWrites).
import { test, expect } from '../../fixtures';
import {
  COUPONS, COUPON_STATES, LIST_HEADERS, NO_MATCH_EN,
  blockCouponWrites, couponColumn, couponRow, couponRows, couponSearch, expectNoCouponWrites, expectRowsOrEmpty,
  openCoupons, restoreTest, selectState, startInTest,
} from './coupon-helpers';

test.describe('Admin coupons: list, search, state filter (#b93722)', () => {
  test('Coupons list: columns Code/Discount/For/Used/Expires/State, every state is a known one, Disabled rows have only Redemptions #b93722 #a10206 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser('admin');
    await startInTest(page);
    const writes = await blockCouponWrites(page);
    try {
      await openCoupons(page);
      // Источник: описание #b93722 п.3 + комментарий программиста 12.10 (список: код, скидка, для кого, погашено/лимит, дата, статус).
      const headers = page.locator('th, [role="columnheader"]');
      for (const h of LIST_HEADERS) await expect(headers.filter({ hasText: new RegExp(`^\\s*${h}\\s*$`) }).first(), `колонка ${h}`).toBeVisible();

      const states = await couponColumn(page, 'State');
      expect(states.length, 'в списке есть купоны').toBeGreaterThan(0);
      for (const s of states) expect(COUPON_STATES as readonly string[], `состояние «${s}»`).toContain(s);

      // Отключённый купон: только Redemptions (нет Edit / Disable). Источник: комментарий программиста п.4, ручная проверка 19.10.
      const disabled = couponRow(page, COUPONS.pct10);
      await expect(disabled).toContainText('Disabled');
      await expect(disabled.getByRole('button', { name: 'Redemptions', exact: true })).toBeVisible();
      await expect(disabled.getByRole('button', { name: 'Edit', exact: true })).toHaveCount(0);
      await expect(disabled.getByRole('button', { name: 'Disable', exact: true })).toHaveCount(0);
      const rows = couponRows(page);
      const n = await rows.count();
      for (let i = 0; i < n; i++) {
        const row = rows.nth(i);
        if (!/\bDisabled\b/.test(await row.innerText())) continue;
        await expect(row.getByRole('button'), 'у Disabled одна кнопка — Redemptions').toHaveCount(1);
      }
    } finally {
      await restoreTest(page);
    }
    expectNoCouponWrites(writes);
  });

  test('Coupons search: by code and by e-mail ignores letter case; no match shows "No coupons match these filters." #b93722 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser('admin');
    await startInTest(page);
    const writes = await blockCouponWrites(page);
    try {
      await openCoupons(page);
      const search = couponSearch(page);
      // Источник: комментарий программиста п.6 — поиск по коду или e-mail.
      await search.fill(COUPONS.onlyOther.toLowerCase());
      await expect(couponRow(page, COUPONS.onlyOther)).toBeVisible();
      await expectRowsOrEmpty(page, (t) => t.toUpperCase().includes(COUPONS.onlyOther), 'все строки — с этим кодом', false);

      await search.fill(COUPONS.onlyOtherEmail.toUpperCase());
      await expect(couponRow(page, COUPONS.onlyOther)).toBeVisible();
      await expectRowsOrEmpty(page, (t) => t.toLowerCase().includes(COUPONS.onlyOtherEmail), 'все строки — для этого e-mail', false);

      await search.fill(`QA-AUTO-NOMATCH-${Date.now()}`);
      await expect(page.getByText(NO_MATCH_EN, { exact: true })).toBeVisible();
      await expect(couponRows(page)).toHaveCount(0);

      await search.fill('');
      await expect(couponRows(page).first()).toBeVisible();
    } finally {
      await restoreTest(page);
    }
    expectNoCouponWrites(writes);
  });

  test('Coupons state filter: Disabled shows only Disabled rows, Active shows only Active rows or "No coupons match these filters." #b93722 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser('admin');
    await startInTest(page);
    const writes = await blockCouponWrites(page);
    try {
      await openCoupons(page);
      // Источник: комментарий программиста п.6 — фильтр по статусу. QA-купоны на 19.10 все Disabled.
      await selectState(page, 'Disabled');
      await expect(couponRow(page, COUPONS.pct10)).toBeVisible();
      await expect(async () => {
        const states = await couponColumn(page, 'State');
        expect(states.length).toBeGreaterThan(0);
        expect(states.filter((s) => s !== 'Disabled')).toEqual([]);
      }).toPass({ timeout: 15_000 });

      await selectState(page, 'Active');
      await expect(couponRow(page, COUPONS.pct10)).toBeHidden();
      await expectRowsOrEmpty(page, (t) => /\bActive\b/.test(t), 'только Active');

      await selectState(page, 'All states');
      await expect(couponRow(page, COUPONS.pct10)).toBeVisible();
    } finally {
      await restoreTest(page);
    }
    expectNoCouponWrites(writes);
  });
});
